import assert from 'node:assert/strict';
import { test } from 'node:test';
import { mergeConfig } from '../src/config.js';

function freeze(value) {
  if (value && typeof value === 'object') {
    for (const item of Object.values(value)) freeze(item);
    Object.freeze(value);
  }
  return value;
}

test('nested sibling keys survive and new keys are added', () => {
  const defaults = freeze({ server: { host: 'localhost', port: 8080 }, level: 'info' });
  const overrides = freeze({ server: { port: 9090, tls: true } });
  assert.deepEqual(mergeConfig(defaults, overrides), {
    server: { host: 'localhost', port: 9090, tls: true }, level: 'info'
  });
  assert.deepEqual(defaults, { server: { host: 'localhost', port: 8080 }, level: 'info' });
  assert.deepEqual(overrides, { server: { port: 9090, tls: true } });
});

test('merge continues at every nested plain-object level', () => {
  let defaults = { retained: 'leaf', changed: 0 };
  let overrides = { changed: 1, added: true };
  let expected = { retained: 'leaf', changed: 1, added: true };
  for (let depth = 0; depth < 40; depth++) {
    defaults = { retained: depth, child: defaults, untouched: { value: depth } };
    overrides = { child: overrides, introduced: depth };
    expected = { retained: depth, child: expected, untouched: { value: depth }, introduced: depth };
  }
  freeze(defaults);
  freeze(overrides);
  assert.deepEqual(mergeConfig(defaults, overrides), expected);
});

test('empty object overrides retain nested defaults; independent branches merge', () => {
  assert.deepEqual(mergeConfig(
    { a: { x: 1, inner: { left: 2, right: 3 } }, b: { keep: 4 }, c: 5 },
    { a: { inner: { right: 30 } }, b: {}, c: { new: 6 } }
  ), { a: { x: 1, inner: { left: 2, right: 30 } }, b: { keep: 4 }, c: { new: 6 } });
});

test('plain objects with null prototypes participate in recursive merging', () => {
  const defaults = { branch: Object.assign(Object.create(null), { keep: 1, child: { x: 2, y: 3 } }) };
  const overrides = { branch: Object.assign(Object.create(null), { child: { y: 4 }, add: 5 }) };
  const result = mergeConfig(defaults, overrides);
  assert.equal(result.branch.keep, 1);
  assert.equal(result.branch.add, 5);
  assert.deepEqual(result.branch.child, { x: 2, y: 4 });
  assert.equal(defaults.branch.child.y, 3);
});

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { mergeConfig } from '../src/config.js';

test('existing shallow behavior, additions, and empty inputs', () => {
  assert.deepEqual(mergeConfig({ level: 'info', color: true }, { level: 'debug', file: 'app.log' }),
    { level: 'debug', color: true, file: 'app.log' });
  assert.deepEqual(mergeConfig({}, {}), {});
  assert.deepEqual(mergeConfig({ a: 1 }, {}), { a: 1 });
  assert.deepEqual(mergeConfig({}, { a: 1 }), { a: 1 });
});

test('non-plain overrides replace whole values, not array indices or instance fields', () => {
  class Settings { constructor() { this.changed = 9; } }
  const replacements = [[ 'c' ], [], null, 'text', 7, false, undefined, new Date(0), /abc/g,
    new Settings(), new Map([['a', 1]]), new Set([1]), () => 42];
  for (const replacement of replacements) {
    for (const previous of [{ keep: 1, changed: 2 }, ['a', 'b'], null, 4]) {
      const defaults = Object.freeze({ value: previous, untouched: true });
      const overrides = Object.freeze({ value: replacement });
      const result = mergeConfig(defaults, overrides);
      assert.deepEqual(result, { value: replacement, untouched: true });
      assert.ok(Object.hasOwn(result, 'value'));
      assert.equal(defaults.value, previous);
      assert.equal(overrides.value, replacement);
    }
  }
});

test('plain-object override replaces non-plain defaults without incorporating their keys', () => {
  class Settings { constructor() { this.old = 1; } }
  for (const previous of [[1, 2], null, 'abc', 5, new Date(0), new Settings()]) {
    assert.deepEqual(mergeConfig({ value: previous }, { value: { fresh: true } }),
      { value: { fresh: true } });
  }
});

test('own enumerable keys and symbols are preserved without copying inherited keys', () => {
  const symbol = Symbol('option');
  const defaults = Object.assign(Object.create({ inherited: 1 }), { keep: 2, [symbol]: 'before' });
  const overrides = Object.assign(Object.create({ unwanted: 3 }), { add: 4, [symbol]: 'after' });
  Object.defineProperty(defaults, 'hidden', { value: 5 });
  assert.deepEqual(mergeConfig(defaults, overrides), { keep: 2, add: 4, [symbol]: 'after' });
});

test('arguments remain unchanged and result is a new top-level object', () => {
  const defaults = { tags: ['a', 'b'], config: { keep: 1 }, level: 'info' };
  const overrides = { tags: ['c'], level: 'debug' };
  const beforeDefaults = structuredClone(defaults);
  const beforeOverrides = structuredClone(overrides);
  const result = mergeConfig(defaults, overrides);
  assert.notEqual(result, defaults);
  assert.notEqual(result, overrides);
  assert.deepEqual(defaults, beforeDefaults);
  assert.deepEqual(overrides, beforeOverrides);
});
